const visual = {
  prepare: function (input) { return []; },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var cols = 4, rows = 3, pad = 24;
    var cell = Math.min((W - pad * 2) / cols, (H - pad * 2) / rows);
    var gw = cell * cols, gh = cell * rows;
    var x0 = (W - gw) / 2, y0 = (H - gh) / 2;
    var paths = [], children = [], i, j;
    for (i = 0; i <= cols; i++) {
      paths.push({ id: 'v' + i, commands: visualSdk.polyline([[x0 + i * cell, y0], [x0 + i * cell, y0 + gh]]) });
      children.push({ type: 'path', pathId: 'v' + i, stroke: '#26354a' });
    }
    for (j = 0; j <= rows; j++) {
      paths.push({ id: 'h' + j, commands: visualSdk.polyline([[x0, y0 + j * cell], [x0 + gw, y0 + j * cell]]) });
      children.push({ type: 'path', pathId: 'h' + j, stroke: '#26354a' });
    }
    return { schemaVersion: 1, sceneId: 'grid-3x4', revision: input.revision,
             viewBox: { x: 0, y: 0, width: W, height: H },
             paths: paths,
             root: { type: 'group', children: children } };
  }
};
